-- SQL Script to Update Email Templates to Premium Designs
-- Copy and paste this into your Supabase SQL Editor

-- 1. Create access_tokens table (if you haven't run the migration yet)
CREATE TABLE IF NOT EXISTS public.access_tokens (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    token TEXT NOT NULL UNIQUE,
    type TEXT NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    used_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Update Welcome Email
INSERT INTO public.email_templates (name, subject, body_html, body_text, tenant_id)
VALUES (
    'Welcome Email',
    'Welcome to the Command Center',
    '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Welcome to the Command Center</title><style>@import url(''https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap'');body{font-family:''Inter'',-apple-system,BlinkMacSystemFont,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;background-color:#020617;color:#cbd5e1;margin:0;padding:0;-webkit-font-smoothing:antialiased}.wrapper{width:100%;table-layout:fixed;background-color:#020617;padding:40px 0}.container{max-width:600px;margin:0 auto;background-color:#0f172a;border-radius:24px;border:1px solid #1e293b;overflow:hidden;box-shadow:0 25px 50px -12px rgba(0,0,0,.5)}.header{padding:48px 40px 32px;text-align:center;background:linear-gradient(180deg,rgba(20,184,166,.05) 0,rgba(15,23,42,0) 100%)}.logo{width:56px;height:56px;margin-bottom:24px}.content{padding:0 40px 48px}h1{font-size:28px;font-weight:800;color:#fff;margin:0 0 16px;letter-spacing:-.025em;line-height:1.2}p{font-size:16px;line-height:1.6;color:#94a3b8;margin:0 0 24px}.card{background-color:#1e293b;border-radius:16px;padding:24px;margin-bottom:32px;border:1px solid #334155}.btn{display:inline-block;padding:16px 32px;background:linear-gradient(135deg,#0d9488 0,#14b8a6 100%);color:#fff!important;text-decoration:none;border-radius:12px;font-weight:700;font-size:16px;text-align:center;box-shadow:0 10px 15px -3px rgba(20,184,166,.3);transition:transform .2s}.footer{padding:32px 40px;background-color:#020617;text-align:center;border-top:1px solid #1e293b}.footer p{font-size:12px;color:#475569;margin:0;line-height:1.5}.accent-text{color:#14b8a6;font-weight:600}.divider{height:1px;background:linear-gradient(90deg,transparent,#1e293b,transparent);margin:32px 0}@media only screen and (max-width:600px){.wrapper{padding:20px 0}.container{border-radius:16px;margin:0 16px}.header{padding:32px 24px 24px}.content{padding:0 24px 32px}h1{font-size:24px}}</style></head><body><div class="wrapper"><div class="container"><div class="header"><img src="https://alphaclonesystems.com/logo.png" alt="AlphaClone" class="logo"><h1>PROVISIONING COMPLETE</h1></div><div class="content"><p>Welcome to the Elite, <strong>{{name}}</strong>.</p><p>Your AlphaClone Command Center is now standing by. We''ve provisioned your workspace, <strong>{{workspace_name}}</strong>, with full enterprise capabilities.</p><div class="card"><h3 style="color:#fff;margin-top:0;font-size:18px">Your Provisioned Assets:</h3><ul style="padding-left:20px;color:#94a3b8;margin-bottom:0"><li style="margin-bottom:8px"><span class="accent-text">AI Strategy Core:</span> Automated lead discovery and market intelligence.</li><li style="margin-bottom:8px"><span class="accent-text">Global Finance:</span> Unified multi-currency treasury and invoicing.</li><li style="margin-bottom:8px"><span class="accent-text">Secure Comms:</span> End-to-end encrypted video and team huddles.</li><li><span class="accent-text">Client Portal:</span> White-labeled delivery experience for your customers.</li></ul></div><p>To begin your session, use the secure access link below.<br><span style="font-size:13px;color:#f43f5e">Note: This link is for your eyes only and will expire in 30 minutes for your protection.</span></p><div style="text-align:center;margin-top:32px"><a href="{{dashboardUrl}}" class="btn">Enter Command Center</a></div><div class="divider"></div><p style="font-size:14px;text-align:center">Questions? Securely contact our ops team at<br><a href="mailto:ops@alphaclonesystems.com" style="color:#14b8a6;text-decoration:none">ops@alphaclonesystems.com</a></p></div><div class="footer"><p>&copy; 2026 AlphaClone Systems. Proprietary & Confidential.</p><p style="margin-top:8px">123 Innovation Drive, Tech City, TC 10101</p></div></div></div></body></html>',
    'Welcome to AlphaClone. Your workspace is ready.',
    NULL
)
ON CONFLICT (name) DO UPDATE SET 
    subject = EXCLUDED.subject,
    body_html = EXCLUDED.body_html,
    body_text = EXCLUDED.body_text;

